7	import * as crypto from 'node:crypto';
8	import { coreEvents } from '../utils/events.js';
9	import { KeychainAvailabilityEvent } from '../telemetry/types.js';
10	import { debugLogger } from '../utils/debugLogger.js';
11	import {
12	  type Keychain,
13	  KeychainSchema,
14	  KEYCHAIN_TEST_PREFIX,
15	} from './keychainTypes.js';
16	import { isRecord } from '../utils/markdownUtils.js';
17	
18	/**
19	 * Service for interacting with OS-level secure storage (e.g. keytar).
20	 */
21	export class KeychainService {
22	  // Track an ongoing initialization attempt to avoid race conditions.
23	  private initializationPromise?: Promise<Keychain | null>;
24	
25	  /**
26	   * @param serviceName Unique identifier for the app in the OS keychain.
27	   */
28	  constructor(private readonly serviceName: string) {}
29	
30	  async isAvailable(): Promise<boolean> {
31	    return (await this.getKeychain()) !== null;
32	  }
33	
34	  /**
35	   * Retrieves a secret for the given account.
36	   * @throws Error if the keychain is unavailable.
37	   */
38	  async getPassword(account: string): Promise<string | null> {
39	    const keychain = await this.getKeychainOrThrow();
40	    return keychain.getPassword(this.serviceName, account);
41	  }
42	
43	  /**
44	   * Securely stores a secret.
45	   * @throws Error if the keychain is unavailable.
46	   */
47	  async setPassword(account: string, value: string): Promise<void> {
48	    const keychain = await this.getKeychainOrThrow();
49	    await keychain.setPassword(this.serviceName, account, value);
50	  }
51	
52	  /**
53	   * Removes a secret from the keychain.
54	   * @returns true if the secret was deleted, false otherwise.
55	   * @throws Error if the keychain is unavailable.
56	   */
57	  async deletePassword(account: string): Promise<boolean> {
58	    const keychain = await this.getKeychainOrThrow();
59	    return keychain.deletePassword(this.serviceName, account);
60	  }
61	
62	  /**
63	   * Lists all account/secret pairs stored under this service.
64	   * @throws Error if the keychain is unavailable.
65	   */
66	  async findCredentials(): Promise<
67	    Array<{ account: string; password: string }>
68	  > {
69	    const keychain = await this.getKeychainOrThrow();
70	    return keychain.findCredentials(this.serviceName);
71	  }
72	
73	  private async getKeychainOrThrow(): Promise<Keychain> {
74	    const keychain = await this.getKeychain();
75	    if (!keychain) {
76	      throw new Error('Keychain is not available');
77	    }
78	    return keychain;
79	  }
80	
81	  private getKeychain(): Promise<Keychain | null> {
82	    return (this.initializationPromise ??= this.initializeKeychain());
83	  }
84	
85	  // High-level orchestration of the loading and testing cycle.
86	  private async initializeKeychain(): Promise<Keychain | null> {
87	    let resultKeychain: Keychain | null = null;
88	
89	    try {
90	      const keychainModule = await this.loadKeychainModule();
91	      if (keychainModule) {
92	        if (await this.isKeychainFunctional(keychainModule)) {
93	          resultKeychain = keychainModule;
94	        } else {
95	          debugLogger.log('Keychain functional verification failed');
96	        }
97	      }
98	    } catch (error) {
99	      // Avoid logging full error objects to prevent PII exposure.
100	      const message = error instanceof Error ? error.message : String(error);
101	      debugLogger.log('Keychain initialization encountered an error:', message);
102	    }
103	
104	    coreEvents.emitTelemetryKeychainAvailability(
105	      new KeychainAvailabilityEvent(resultKeychain !== null),
106	    );
107	
108	    return resultKeychain;
109	  }
110	
111	  // Low-level dynamic loading and structural validation.
112	  private async loadKeychainModule(): Promise<Keychain | null> {
113	    const moduleName = 'keytar';
114	    const module: unknown = await import(moduleName);
115	    const potential = (isRecord(module) && module['default']) || module;
116	
117	    const result = KeychainSchema.safeParse(potential);
118	    if (result.success) {
119	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
120	      return potential as Keychain;
121	    }
122	
123	    debugLogger.log(
124	      'Keychain module failed structural validation:',
125	      result.error.flatten().fieldErrors,
126	    );
127	    return null;
128	  }
129	
130	  // Performs a set-get-delete cycle to verify keychain functionality.
131	  private async isKeychainFunctional(keychain: Keychain): Promise<boolean> {
132	    const testAccount = `${KEYCHAIN_TEST_PREFIX}${crypto.randomBytes(8).toString('hex')}`;
133	    const testPassword = 'test';
134	
135	    await keychain.setPassword(this.serviceName, testAccount, testPassword);
136	    const retrieved = await keychain.getPassword(this.serviceName, testAccount);
137	    const deleted = await keychain.deletePassword(
138	      this.serviceName,
139	      testAccount,
140	    );
141	
142	    return deleted && retrieved === testPassword;
143	  }
144	}
