7	import { BaseTokenStorage } from './base-token-storage.js';
8	import { FileTokenStorage } from './file-token-storage.js';
9	import {
10	  TokenStorageType,
11	  type TokenStorage,
12	  type OAuthCredentials,
13	} from './types.js';
14	import { coreEvents } from '../../utils/events.js';
15	import { TokenStorageInitializationEvent } from '../../telemetry/types.js';
16	
17	const FORCE_FILE_STORAGE_ENV_VAR = 'GEMINI_FORCE_FILE_STORAGE';
18	
19	export class HybridTokenStorage extends BaseTokenStorage {
20	  private storage: TokenStorage | null = null;
21	  private storageType: TokenStorageType | null = null;
22	  private storageInitPromise: Promise<TokenStorage> | null = null;
23	
24	  constructor(serviceName: string) {
25	    super(serviceName);
26	  }
27	
28	  private async initializeStorage(): Promise<TokenStorage> {
29	    const forceFileStorage = process.env[FORCE_FILE_STORAGE_ENV_VAR] === 'true';
30	
31	    if (!forceFileStorage) {
32	      try {
33	        const { KeychainTokenStorage } = await import(
34	          './keychain-token-storage.js'
35	        );
36	        const keychainStorage = new KeychainTokenStorage(this.serviceName);
37	
38	        const isAvailable = await keychainStorage.isAvailable();
39	        if (isAvailable) {
40	          this.storage = keychainStorage;
41	          this.storageType = TokenStorageType.KEYCHAIN;
42	
43	          coreEvents.emitTelemetryTokenStorageType(
44	            new TokenStorageInitializationEvent('keychain', forceFileStorage),
45	          );
46	
47	          return this.storage;
48	        }
49	      } catch (_e) {
50	        // Fallback to file storage if keychain fails to initialize
51	      }
52	    }
53	
54	    this.storage = new FileTokenStorage(this.serviceName);
55	    this.storageType = TokenStorageType.ENCRYPTED_FILE;
56	
57	    coreEvents.emitTelemetryTokenStorageType(
58	      new TokenStorageInitializationEvent('encrypted_file', forceFileStorage),
59	    );
60	
61	    return this.storage;
62	  }
63	
64	  private async getStorage(): Promise<TokenStorage> {
65	    if (this.storage !== null) {
66	      return this.storage;
67	    }
68	
69	    // Use a single initialization promise to avoid race conditions
70	    if (!this.storageInitPromise) {
71	      this.storageInitPromise = this.initializeStorage();
72	    }
73	
74	    // Wait for initialization to complete
75	    return this.storageInitPromise;
76	  }
77	
78	  async getCredentials(serverName: string): Promise<OAuthCredentials | null> {
79	    const storage = await this.getStorage();
80	    return storage.getCredentials(serverName);
81	  }
82	
83	  async setCredentials(credentials: OAuthCredentials): Promise<void> {
84	    const storage = await this.getStorage();
85	    await storage.setCredentials(credentials);
86	  }
87	
88	  async deleteCredentials(serverName: string): Promise<void> {
89	    const storage = await this.getStorage();
90	    await storage.deleteCredentials(serverName);
91	  }
92	
93	  async listServers(): Promise<string[]> {
94	    const storage = await this.getStorage();
95	    return storage.listServers();
96	  }
97	
98	  async getAllCredentials(): Promise<Map<string, OAuthCredentials>> {
99	    const storage = await this.getStorage();
100	    return storage.getAllCredentials();
101	  }
102	
103	  async clearAll(): Promise<void> {
104	    const storage = await this.getStorage();
105	    await storage.clearAll();
106	  }
107	
108	  async getStorageType(): Promise<TokenStorageType> {
109	    await this.getStorage();
110	    return this.storageType!;
111	  }
112	}
